function renderRoster(){const pos=$('roster').scrollTop;$('rosterCount').textContent=filtered.length+' / '+units.length;$('roster').innerHTML=filtered.map(u=>`<button class="unitrow ${selected.has(u.id)?'selected':''}" data-id="${u.id}" aria-pressed="${selected.has(u.id)}" style="--c:${colors[u.faction]}"><span class="box">${selected.has(u.id)?'�':''}</span><img src="${esc(u.image)}" alt="" loading="lazy"><span><b>${esc(u.name)}</b><small>${u.faction} � ${esc(u.tier||'-')} � ${esc(u.category.replace('-buildings',''))}</small></span><span class="dot"></span></button>`).join('')||'<p class="empty">No matching units.</p>';$('roster').scrollTop=pos}
function metricExplanation(){const y=$('y').value,d=$('divide').value;const amounts={metal:'Metal cost',energy:'Energy cost',health:'Health points',dps:'Damage per second',range:'Weapon range',sight:'Sight range',speed:'Movement speed','build time':'Build time',buildpower:'Build power',weapon_alpha:'Maximum weapon damage per shot'};const per={metal:'1 metal spent',energy:'1 energy spent',health:'1 health point',dps:'1 damage per second','build time':'1 build-time unit'};const amount=amounts[y]||name(y);if(!d)return {label:amount,detail:'No division is applied.'};let detail='Calculated as '+name(y).toLowerCase()+' ÷ '+name(d).toLowerCase()+'.';if(y==='health'&&d==='metal')detail+=' Higher means more health for the same metal.';if(y==='metal'&&d==='health')detail+=' Lower means less metal spent for the same health.';return {label:amount+' per '+(per[d]||('1 unit of '+name(d).toLowerCase())),detail}}
