function renderCards(){const chosen=units.filter(u=>selected.has(u.id));if(view==='bars')chosen.sort(compareRankedUnits);$('selectedCards').innerHTML=chosen.length?chosen.slice(0,12).map(u=>`<article class="unitcard" style="--c:${colors[u.faction]}"><button class="remove" data-remove="${u.id}" aria-label="Remove ${esc(u.name)}">x</button><div class="cardtop"><img src="${esc(u.image)}" alt="${esc(u.name)}" loading="lazy"><div><h3>${esc(u.name)}</h3><small>${u.faction} � ${esc(u.tier)} � ${esc(u.role)}</small><a href="${u.url}" target="_blank" rel="noreferrer">Official unit page ?</a></div></div><div class="cardstats">${['metal','dps','range','health','speed','sight'].map(k=>`<div><small>${name(k)}</small><b>${rangeText(bounds(u,k))}</b></div>`).join('')}</div><details><summary>All stats & weapons</summary>${Object.entries(u.stats).map(([k,v])=>`<div>${esc(name(k))}: ${rangeText(bounds(u,k))}</div>`).join('')}${u.weapons.map(w=>`<div class="weapon"><b>${esc(w.name)}</b><br>${Object.entries(w).filter(([k,v])=>k!=='range_damage_factor'&&typeof v==='number').map(([k,v])=>esc(name(k))+': '+rangeText(w.ranges?.[k]||{min:v,max:v})).join(' � ')}</div>`).join('')}</details></article>`).join('')+(chosen.length>12?`<p style="color:var(--muted);font-size:12px">+ ${chosen.length-12} more selected. Use Side by side to compare all ${chosen.length} units.</p>`:''):'<div class="empty"><span>Select units in the roster to start comparing.</span></div>'}
