function tip(e){const t=e.target.closest('[data-id]'),tooltip=$('tooltip');if(!t||!$('visual').contains(t)){tooltip.hidden=true;return}const u=units.find(u=>u.id===t.dataset.id);if(!u)return;if(tooltip.hidden||tip.lastId!==u.id){const metrics=['metal','energy','health','dps','range','sight','speed','build time'];tooltip.className='tooltip hovercard';tooltip.innerHTML=`<article class="hover-unit" style="--c:${colors[u.faction]}"><div class="hover-header"><img src="${esc(u.image)}" alt=""><div><strong>${esc(u.name)}</strong><p>${u.faction} · ${esc(u.tier)}</p><p>${esc(u.role)}</p></div></div><div class="hover-stats">${metrics.map(k=>`<div><span>${esc(name(k))}</span><b>${rangeText(bounds(u,k))}</b></div>`).join('')}</div><div class="hover-current">${view==='scatter'?`<div><span>${esc(name($('x').value))}</span><b>${rangeText(bounds(u,$('x').value))}</b></div>`:''}<div><span>${esc(yname())}</span><b>${rangeText(ybounds(u))}</b></div></div><p class="hover-foot">${touchAction(e)?'Release to hide · Tap for removal options':'Click to '+(selected.has(u.id)?'remove':'select')+' unit'}</p></article>`;tip.lastId=u.id}tooltip.hidden=false;const box=t.getBoundingClientRect(),x=e.clientX??box.x+box.width/2,y=e.clientY??box.y+box.height/2,size=tooltip.getBoundingClientRect();let left=x+18,top=y+18;if(left+size.width>innerWidth-8)left=x-size.width-18;if(top+size.height>innerHeight-8)top=y-size.height-18;tooltip.style.left=Math.max(8,Math.min(left,innerWidth-size.width-8))+'px';tooltip.style.top=Math.max(8,Math.min(top,innerHeight-size.height-8))+'px'}
